class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        if amount <= 0:
            return False
        self.balance += amount
        return True

    def withdraw(self, amount):
        if amount <= 0 or amount > self.balance:
            return False
        self.balance -= amount
        return True

    def get_balance(self):
        return self.balance


owner, start = input().split()
account = BankAccount(owner, int(start))

q = int(input())
for _ in range(q):
    parts = input().split()
    command = parts[0]
    if command == "DEPOSIT":
        print("OK" if account.deposit(int(parts[1])) else "FAILED")
    elif command == "WITHDRAW":
        print("OK" if account.withdraw(int(parts[1])) else "FAILED")
    elif command == "BALANCE":
        print(account.get_balance())

class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)

    def resize(self, width, height):
        self.width = width
        self.height = height

    def __str__(self):
        return f"Rectangle(width={self.width}, height={self.height})"


w, h = map(int, input().split())
rect = Rectangle(w, h)

q = int(input())
for _ in range(q):
    parts = input().split()
    if parts[0] == "AREA":
        print(rect.area())
    elif parts[0] == "PERIMETER":
        print(rect.perimeter())
    elif parts[0] == "PRINT":
        print(rect)
    elif parts[0] == "RESIZE":
        rect.resize(int(parts[1]), int(parts[2]))

class Circle:
    PI = 3.14159

    def __init__(self, radius):
        if radius <= 0:
            raise ValueError("radius must be positive")
        self.radius = radius

    def set_radius(self, radius):
        if radius <= 0:
            raise ValueError("radius must be positive")
        self.radius = radius

    def area(self):
        return Circle.PI * self.radius * self.radius

    def circumference(self):
        return 2 * Circle.PI * self.radius


radius = float(input())
q = int(input())

try:
    circle = Circle(radius)
except ValueError:
    print("INVALID RADIUS")
else:
    for _ in range(q):
        parts = input().split()
        if parts[0] == "AREA":
            print(f"{circle.area():.2f}")
        elif parts[0] == "CIRCUMFERENCE":
            print(f"{circle.circumference():.2f}")
        elif parts[0] == "SET":
            try:
                circle.set_radius(float(parts[1]))
            except ValueError:
                print("INVALID RADIUS")

class Student:
    def __init__(self, name):
        self.name = name
        self.grades = []          # one list per student

    def add_grade(self, subject, grade):
        if grade < 0 or grade > 100:
            return False
        self.grades.append((subject, grade))
        return True

    def average(self):
        if not self.grades:
            return None
        return sum(g for _, g in self.grades) / len(self.grades)

    def letter(self):
        avg = self.average()
        if avg is None:
            return None
        if avg >= 90:
            return "A"
        if avg >= 80:
            return "B"
        if avg >= 70:
            return "C"
        if avg >= 60:
            return "D"
        return "F"


student = Student(input())

q = int(input())
for _ in range(q):
    parts = input().split()
    if parts[0] == "ADD":
        print("OK" if student.add_grade(parts[1], int(parts[2])) else "INVALID")
    elif parts[0] == "AVERAGE":
        avg = student.average()
        print("NO GRADES" if avg is None else f"{avg:.2f}")
    elif parts[0] == "LETTER":
        grade = student.letter()
        print("NO GRADES" if grade is None else grade)
    elif parts[0] == "COUNT":
        print(len(student.grades))

class Book:
    def __init__(self, title, author, year):
        self.title = title
        self.author = author
        self.year = year

    def set_year(self, year):
        self.year = year

    def __str__(self):
        return f"{self.title} by {self.author} ({self.year})"

    def __repr__(self):
        return f"Book({self.title!r}, {self.author!r}, {self.year})"


title = input()
author = input()
year = int(input())
book = Book(title, author, year)

q = int(input())
for _ in range(q):
    parts = input().split()
    if parts[0] == "STR":
        print(book)
    elif parts[0] == "REPR":
        print(repr(book))
    elif parts[0] == "LIST":
        print([book])
    elif parts[0] == "YEAR":
        book.set_year(int(parts[1]))

class Ticket:
    count = 0                       # class attribute: shared by all tickets

    def __init__(self, name):
        Ticket.count += 1
        self.id = Ticket.count      # instance attributes: one per ticket
        self.name = name

    def __str__(self):
        return f"Ticket {self.id}: {self.name}"


tickets = {}

q = int(input())
for _ in range(q):
    parts = input().split()
    if parts[0] == "NEW":
        ticket = Ticket(parts[1])
        tickets[ticket.id] = ticket
        print(f"Created ticket {ticket.id} for {ticket.name}")
    elif parts[0] == "COUNT":
        print(Ticket.count)
    elif parts[0] == "SHOW":
        ticket_id = int(parts[1])
        if ticket_id in tickets:
            print(tickets[ticket_id])
        else:
            print("NOT FOUND")

class BadTeam:
    members = []                    # TRAP: one list shared by every BadTeam

    def __init__(self, name):
        self.name = name

    def add(self, person):
        self.members.append(person)


class GoodTeam:
    def __init__(self, name):
        self.name = name
        self.members = []           # a new list for every GoodTeam

    def add(self, person):
        self.members.append(person)


bad_teams = {}
good_teams = {}

q = int(input())
for _ in range(q):
    parts = input().split()
    if parts[0] == "CREATE":
        bad_teams[parts[1]] = BadTeam(parts[1])
        good_teams[parts[1]] = GoodTeam(parts[1])
