class Wallet:
    def __init__(self):
        self._balance = 0
        self._log = []

    def balance(self):
        return self._balance

    def credit(self, amount):
        if amount <= 0:
            return "INVALID"
        self._balance += amount
        self._log.append(f"CREDIT {amount}")
        return "OK"

    def debit(self, amount):
        if amount <= 0:
            return "INVALID"
        fee = max(1, amount // 50)
        if amount + fee > self._balance:
            self._log.append(f"DECLINED {amount}")
            return "DECLINED"
        self._balance -= amount + fee
        self._log.append(f"DEBIT {amount} FEE {fee}")
        return "OK"

    def history(self):
        return self._log


wallet = Wallet()

q = int(input())
for _ in range(q):
    parts = input().split()
    if parts[0] == "CREDIT":
        print(wallet.credit(int(parts[1])))
    elif parts[0] == "DEBIT":
        print(wallet.debit(int(parts[1])))
    elif parts[0] == "BALANCE":
        print(wallet.balance())
    elif parts[0] == "HISTORY":
        log = wallet.history()
        if log:
            for line in log:
                print(line)
        else:
            print("NO TRANSACTIONS")

class Item:
    def __init__(self, name, price, qty):
        self.name = name
        self.price = price
        self.qty = qty

    def subtotal(self):
        return self.price * self.qty


class Cart:
    def __init__(self):
        self.items = {}

    def add(self, name, price, qty):
        if name in self.items:
            self.items[name].qty += qty      # keep the old price
        else:
            self.items[name] = Item(name, price, qty)

    def remove(self, name, qty):
        if name not in self.items:
            return False
        item = self.items[name]
        if qty >= item.qty:
            del self.items[name]
        else:
            item.qty -= qty
        return True

    def total(self):
        return sum(item.subtotal() for item in self.items.values())


cart = Cart()

q = int(input())
for _ in range(q):
    parts = input().split()
    if parts[0] == "ADD":
        cart.add(parts[1], float(parts[2]), int(parts[3]))
    elif parts[0] == "REMOVE":
        print("OK" if cart.remove(parts[1], int(parts[2])) else "NOT FOUND")
    elif parts[0] == "TOTAL":
        print(f"{cart.total():.2f}")
    elif parts[0] == "LIST":
        if cart.items:
            for item in cart.items.values():
                print(f"{item.name} x{item.qty} @ {item.price:.2f}")
        else:
            print("EMPTY")

class Temperature:
    def __init__(self, value, unit):
        self.value = value
        self.unit = unit

    def set(self, value, unit):
        self.value = value
        self.unit = unit

    def to_celsius(self):
        if self.unit == "C":
            return self.value
        if self.unit == "F":
            return (self.value - 32) * 5 / 9
        return self.value - 273.15          # unit K

    def to_fahrenheit(self):
        return self.to_celsius() * 9 / 5 + 32

    def to_kelvin(self):
        return self.to_celsius() + 273.15


value, unit = input().split()
temp = Temperature(float(value), unit)

q = int(input())
for _ in range(q):
    parts = input().split()
    if parts[0] == "C":
        print(f"{temp.to_celsius():.2f}")
    elif parts[0] == "F":
        print(f"{temp.to_fahrenheit():.2f}")
    elif parts[0] == "K":
        print(f"{temp.to_kelvin():.2f}")
    elif parts[0] == "SET":
        temp.set(float(parts[1]), parts[2])

class Playlist:
    def __init__(self):
        self.songs = []
        self.index = 0

    def add(self, song):
        self.songs.append(song)

    def current(self):
        if not self.songs:
            return None
        return self.songs[self.index]

    def next_track(self):
        if not self.songs:
            return None
        self.index = (self.index + 1) % len(self.songs)
        return self.songs[self.index]

    def prev_track(self):
        if not self.songs:
            return None
        self.index = (self.index - 1) % len(self.songs)
        return self.songs[self.index]


playlist = Playlist()

q = int(input())
for _ in range(q):
    command, _, rest = input().partition(" ")
    if command == "ADD":
        playlist.add(rest)
    else:
        if command == "CURRENT":
            song = playlist.current()
        elif command == "NEXT":
            song = playlist.next_track()
        else:
            song = playlist.prev_track()
        print("EMPTY" if song is None else song)

class Library:
    def __init__(self):
        self.books = {}             # title -> borrower name, or None

    def add_book(self, title):
        if title in self.books:
            return "EXISTS"
        self.books[title] = None
        return "ADDED"

    def borrow(self, name, title):
        if title not in self.books:
            return "NOT FOUND"
        if self.books[title] is not None:
            return "UNAVAILABLE"
        self.books[title] = name
        return "OK"

    def return_book(self, title):
        if title not in self.books:
            return "NOT FOUND"
        if self.books[title] is None:
            return "NOT BORROWED"
        self.books[title] = None
        return "OK"

    def status(self, title):
        if title not in self.books:
            return "NOT FOUND"
        if self.books[title] is None:
            return "available"
        return f"borrowed by {self.books[title]}"


library = Library()

q = int(input())
for _ in range(q):
    line = input()
    command = line.split(" ", 1)[0]
    if command == "ADD":
        print(library.add_book(line.split(" ", 1)[1]))
    elif command == "BORROW":
        _, name, title = line.split(" ", 2)
        print(library.borrow(name, title))
    elif command == "RETURN":
        print(library.return_book(line.split(" ", 1)[1]))
    elif command == "STATUS":
        print(library.status(line.split(" ", 1)[1]))
    elif command == "REPORT":
        if library.books:
            for title in library.books:
                print(f"{title}: {library.status(title)}")
        else:
            print("EMPTY")

import math


class Vector2D:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def add(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def dot(self, other):
        return self.x * other.x + self.y * other.y

    def magnitude(self):
        return math.sqrt(self.x ** 2 + self.y ** 2)

    def __repr__(self):
        return f"Vector2D({self.x}, {self.y})"


q = int(input())
for _ in range(q):
    parts = input().split()
    nums = [int(p) for p in parts[1:]]
    if parts[0] == "ADD":
        print(Vector2D(nums[0], nums[1]).add(Vector2D(nums[2], nums[3])))
    elif parts[0] == "DOT":
        print(Vector2D(nums[0], nums[1]).dot(Vector2D(nums[2], nums[3])))
    elif parts[0] == "MAG":
        print(f"{Vector2D(nums[0], nums[1]).magnitude():.3f}")

from collections import deque


class RateLimiter:
    def __init__(self, k, window):
        self.k = k
        self.window = window
        self.times = {}             # user -> deque of allowed action times

    def _clean(self, user, t):
        q = self.times.setdefault(user, deque())
        while q and q[0] <= t - self.window:     # too old: outside (t - window, t]
            q.popleft()
        return q

    def allow(self, user, t):
        q = self._clean(user, t)
        if len(q) < self.k:
            q.append(t)
            return True
        return False

    def usage(self, user, t):
        return len(self._clean(user, t))


k, window = map(int, input().split())
limiter = RateLimiter(k, window)

q = int(input())
for _ in range(q):
    parts = input().split()
    user, t = parts[1], int(parts[2])
    if parts[0] == "REQ":
        print("ALLOWED" if limiter.allow(user, t) else "BLOCKED")
    elif parts[0] == "USAGE":
        print(limiter.usage(user, t))

class Course:
    def __init__(self, code, prereqs):
        self.code = code
        self.prereqs = prereqs


class Student:
    def __init__(self, name):
        self.name = name
        self.completed = set()
        self.enrolled = set()

    def enroll(self, course):
        if course.code in self.completed:
            return "ALREADY COMPLETED"
        if course.code in self.enrolled:
            return "ALREADY ENROLLED"
        missing = [p for p in course.prereqs if p not in self.completed]
        if missing:
            return "MISSING " + " ".join(missing)
        self.enrolled.add(course.code)
        return "ENROLLED"

    def complete(self, code):
        if code not in self.enrolled:
            return "NOT ENROLLED"
        self.enrolled.remove(code)
        self.completed.add(code)
        return "COMPLETED"


courses = {}
students = {}

q = int(input())
for _ in range(q):
    parts = input().split()
    command = parts[0]
    if command == "COURSE":
        courses[parts[1]] = Course(parts[1], parts[2:])
        continue

    name = parts[1]
    if name not in students:
        students[name] = Student(name)
    student = students[name]

    if command == "ENROLL":
        code = parts[2]
        if code not in courses:
            print("UNKNOWN COURSE")
        else:
            print(student.enroll(courses[code]))
    elif command == "COMPLETE":
        print(student.complete(parts[2]))
    elif command == "STATUS":
        done = " ".join(sorted(student.completed)) or "none"
        now = " ".join(sorted(student.enrolled)) or "none"
        print(f"completed: {done} | enrolled: {now}")

class Inventory:
    def __init__(self):
        self.items = {}     # sku -> {"stock": int, "threshold": int}

    def is_low(self, sku):
        item = self.items[sku]
        return item["stock"] < item["threshold"]

    def add_sku(self, sku, qty, threshold):
        if sku in self.items:
            return "EXISTS"
        self.items[sku] = {"stock": qty, "threshold": threshold}
        return "OK"

    def restock(self, sku, qty):
        if sku not in self.items:
            return "NOT FOUND"
        self.items[sku]["stock"] += qty
        return "OK"

    def sell(self, sku, qty):
        if sku not in self.items:
            return "NOT FOUND", None
        item = self.items[sku]
        if qty > item["stock"]:
            return "INSUFFICIENT", None
        was_low = self.is_low(sku)
        item["stock"] -= qty
        if not was_low and self.is_low(sku):
            return "OK", f"ALERT {sku} {item['stock']}"
        return "OK", None


inventory = Inventory()

q = int(input())
for _ in range(q):
    parts = input().split()
    command = parts[0]
    if command == "ADD":
        print(inventory.add_sku(parts[1], int(parts[2]), int(parts[3])))
    elif command == "RESTOCK":
        print(inventory.restock(parts[1], int(parts[2])))
    elif command == "SELL":
        result, alert = inventory.sell(parts[1], int(parts[2]))
        print(result)
        if alert is not None:
            print(alert)
    elif command == "REPORT":
        if inventory.items:
            for sku, item in inventory.items.items():
                suffix = " LOW" if inventory.is_low(sku) else ""
                print(f"{sku} {item['stock']}{suffix}")
        else:
            print("EMPTY")
